questionvariables.text:
/* Define the combinations function */ 
n_select:4;   /* Number of books to select */ 
aa:rand(5)+2;
n_paperback: n_select+aa;   /* Number of paperback books */ 
bb:rand(5)+4;
n_hardcopy: n_paperback+bb;   /* Number of hard-copy books */ 

n: n_paperback+n_hardcopy; /* Total number of books */
/* Define the total number of outcomes */ 
total_outcomes: binomial(n, n_select);  
/* Define the number of favorable outcomes */ 
favorable_outcomes: binomial(n_paperback, 2) * binomial(n_hardcopy, 2) + binomial(n_paperback, 3) * binomial(n_hardcopy, 1) + binomial(n_paperback, 4)*binomial(n_hardcopy, 0);  
/* Calculate the probability */ 
probability: favorable_outcomes / total_outcomes; 
ta:probability;
